def tiles(word, y, missing=False, highlight=False):
 r=''
 for i in range(6):
  x=5+29*i;char=word[i] if i<len(word) else '?';fill='#c5dab7' if highlight and char=='a' else '#e0e5dc'
  r+=f'<rect x="{x}" y="{y}" width="24" height="36" rx="4" fill="{fill}" stroke="#819581"'+(' stroke-dasharray="3 2"' if missing and i==5 else '')+'/>'
  r+=f'<text x="{x+12}" y="{y+26}" font-size="23">{char}</text>'
 return r
